// AttentionSoftmaxWithSoftcappingAndDropout op_host
// Tiling calculation + strategy dispatch + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_attention_softmax_softcap_dropout_merge_n.h"
#include "aclrtlaunch_attention_softmax_softcap_dropout_splitd.h"

// ---------------------------------------------------------------------------
// Tiling constants
// ---------------------------------------------------------------------------

constexpr int32_t DEFAULT_BLOCK_M = 64;
constexpr int32_t DEFAULT_ROW_FACTOR = 8;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;
constexpr float DEFAULT_SOFTCAP = 30.0f;

// ---------------------------------------------------------------------------
// Host function
// ---------------------------------------------------------------------------

namespace ascend_kernel {

at::Tensor attention_softmax_softcap_dropout(const at::Tensor &attn_weights)
{
    TORCH_CHECK(attn_weights.dim() == 2, "attn_weights must be 2D [M, N]");
    TORCH_CHECK(
        attn_weights.scalar_type() == at::kFloat || attn_weights.scalar_type() == at::kHalf ||
            attn_weights.scalar_type() == at::kBFloat16,
        "attn_weights must be float16, float32, or bfloat16");
    TORCH_CHECK(attn_weights.is_contiguous(), "attn_weights must be contiguous");

    int32_t M = static_cast<int32_t>(attn_weights.sizes()[0]);
    int32_t N = static_cast<int32_t>(attn_weights.sizes()[1]);

    int32_t mNum = (M + DEFAULT_BLOCK_M - 1) / DEFAULT_BLOCK_M;
    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES, std::max<int32_t>(1, mNum));
    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;

    at::Tensor output = at::empty_like(attn_weights);

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (attn_weights.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (attn_weights.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // All tiling params as left values (required by EXEC_KERNEL_CMD)
    int32_t blockM = DEFAULT_BLOCK_M;
    int32_t rowFactor = DEFAULT_ROW_FACTOR;
    float softcapVal = DEFAULT_SOFTCAP;
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // Strategy dispatch: select kernel name and params
    if (N <= 1024) {
        EXEC_KERNEL_CMD(attention_softmax_softcap_dropout_merge_n, blockDim,
                        attn_weights, output,
                        M, N, blockM, usedCoreNum, tasksPerCore, rowFactor, softcapVal,
                        dtypeFlag);
    } else {
        EXEC_KERNEL_CMD(attention_softmax_softcap_dropout_splitd, blockDim,
                        attn_weights, output,
                        M, N, blockM, usedCoreNum, tasksPerCore, softcapVal,
                        dtypeFlag);
    }

    return output;
}

}  // namespace ascend_kernel
