130	// =========================================================================
131	// Strategy 1: merge_n — preferred when N <= 1024
132	// Processes rowFactor rows at a time. Full row softcapping + softmax in UB.
133	// =========================================================================
134	
135	template <typename dataType>
136	class SoftmaxSoftcapMergeNKernel {
137	public:
138	    __aicore__ inline void Init(
139	        GM_ADDR x, GM_ADDR y,
140	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
141	        int32_t tasksPerCore, int32_t rowFactor, float softcapVal)
142	    {
143	        this->M = M;
144	        this->N = N;
145	        this->blockM = blockM;
146	        this->usedCoreNum = usedCoreNum;
147	        this->tasksPerCore = tasksPerCore;
148	        this->rowFactor = rowFactor;
149	        this->softcapVal = softcapVal;
150	
151	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), static_cast<uint64_t>(M) * N);
152	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(M) * N);
153

154	        if ASCEND_IS_AIV { InitAivBuffers(); }
155	    }
156	
157	    __aicore__ inline void InitAivBuffers()
158	    {
159	        subBlockRows_ = blockM / AscendC::GetSubBlockNum();
160	        rowLoops_ = subBlockRows_ / rowFactor;
161	
162	        pipe.InitBuffer(xInQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
163	        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
164	        pipe.InitBuffer(tmpBuf_, kMergeRowFactor * N * sizeof(float));
165	        pipe.InitBuffer(reduceBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
166	        pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
167	        pipe.InitBuffer(bcastMaxTmpBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
168	        pipe.InitBuffer(bcastSumTmpBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
169	        if constexpr (!std::is_same_v<dataType, float>) {
170	            pipe.InitBuffer(xCastBuf_, kMergeRowFactor * N * sizeof(float));
171	            pipe.InitBuffer(yCastBuf_, kMergeRowFactor * N * sizeof(float));
172	        }
173	    }
174	
175	    __aicore__ inline void Process()
176	    {
177	        if ASCEND_IS_AIV {
178	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
179	            const int subBlockIdx = AscendC::GetSubBlockIdx();
180	
181	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
182	                const int bx = coreIdx * tasksPerCore + localIdx;
183	                if (bx >= (M + blockM - 1) / blockM) {
184	                    continue;
185	                }
186	
187	                for (int r = 0; r < rowLoops_; ++r) {
188	                    const int rowBase = bx * blockM + subBlockIdx * subBlockRows_ + r * rowFactor;
189	                    const int validRows = M - rowBase;
190	                    if (validRows > 0) {
191	                        const int actualRows = (validRows >= kMergeRowFactor) ? kMergeRowFactor : validRows;
192	                        ProcessRows(rowBase, actualRows);
193	                    }
194	                }
195	            }
196	        }
197	    }
198	
199	private:
200	    __aicore__ inline void ProcessSingleRow(int rowIdx)
201	    {
202	        // CopyIn one row
203	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
204	        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
205	        xInQueue_.EnQue(xInLocal_);
206	
207	        // Compute
208	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
209	        xInLocal_ = xInQueue_.DeQue<dataType>();
210	        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, N);
211	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
212	
213	        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
214	        sumLocal_ = sumBuf_.Get<float>();
215	        tmpLocal_ = tmpBuf_.Get<float>();
216	
217	        // Softcapping in-place
218	        SoftcapTile(xLocal_, tmpLocal_, static_cast<uint32_t>(N), softcapVal);
219	
220	        // Softmax on one row using ReduceSum (R-block scalar fallback)
221	        AscendC::ReduceMax<float>(sumLocal_, xLocal_, reduceTmpLocal_, N);
222	        float rowMax = sumLocal_.GetValue(0);
223	        AscendC::PipeBarrier<PIPE_ALL>();
224	
225	        AscendC::Adds(xLocal_, xLocal_, -rowMax, N);
226	        AscendC::Exp(xLocal_, xLocal_, N);
227	        AscendC::ReduceSum<float>(sumLocal_, xLocal_, reduceTmpLocal_, N);
228	        float rowSum = sumLocal_.GetValue(0);
229	        AscendC::PipeBarrier<PIPE_ALL>();
230	
231	        float invSum = (rowSum > 0.0f) ? (1.0f / rowSum) : 1.0f;
232	        AscendC::Muls(yLocal_, xLocal_, invSum, N);
233	
234	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, N);
235	
236	        xInQueue_.FreeTensor(xInLocal_);
237	        yOutQueue_.EnQue(yOutLocal_);
238	
239	        // CopyOut
240	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
241	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N], yOutLocal_, static_cast<uint32_t>(N));
242	        yOutQueue_.FreeTensor(yOutLocal_);
243	    }
244	
245	    __aicore__ inline void ProcessRows(int rowBase, int actualRows)
246	    {
247	        if (actualRows < kMergeRowFactor) {
248	            for (int r = 0; r < actualRows; ++r) {
249	                ProcessSingleRow(rowBase + r);
250	            }
251	            return;
252	        }
253	
254	        const int tileSize = kMergeRowFactor * N;
255	
256	        // CopyIn
257	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
258	        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowBase) * N], static_cast<uint32_t>(tileSize));
259	        xInQueue_.EnQue(xInLocal_);
260	
261	        // Compute
262	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
263	        xInLocal_ = xInQueue_.DeQue<dataType>();
264	        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, tileSize);
265	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
266	
267	        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
268	        sumLocal_ = sumBuf_.Get<float>();
269	        tmpLocal_ = tmpBuf_.Get<float>();
270	
271	        // Softcapping
272	        SoftcapTile(xLocal_, tmpLocal_, static_cast<uint32_t>(tileSize), softcapVal);
273	
274	        // Softmax: reduce_max over dim=-1 (AR pattern)
275	        const uint32_t reduceShape[2] = {
276	            static_cast<uint32_t>(kMergeRowFactor),
277	            static_cast<uint32_t>(N),
278	        };
279	        AscendC::ReduceMax<float, AscendC::Pattern::Reduce::AR, false>(
280	            sumLocal_, xLocal_, reduceTmpLocal_, reduceShape, true);
281	
282	        // Broadcast max
283	        const uint32_t maxSrcShape[2] = {static_cast<uint32_t>(kMergeRowFactor), 1U};

