92	    AscendC::LocalTensor<T> &out,
93	    AscendC::LocalTensor<float> &src,
94	    int32_t count)
95	{
96	    if constexpr (!std::is_same_v<T, float>) {
97	        AscendC::Cast(out, src, OutputRoundModeHelper<T>(), count);
98	        AscendC::PipeBarrier<PIPE_V>();
99	    }
100	}
101	
102	// ---------------------------------------------------------------------------
103	// Softcapping + Softmax compute (operates on float32 tiles)
104	// ---------------------------------------------------------------------------
105	
106	// Apply softcapping in-place on a float32 tile of given count
107	// tanh decomposition: tanh(z) = (exp(2*z) - 1) / (exp(2*z) + 1)
108	__aicore__ inline void SoftcapTile(
109	    AscendC::LocalTensor<float> &tile,
110	    AscendC::LocalTensor<float> &tmpBuf,
111	    uint32_t count,
112	    float softcapVal)
113	{
114	    // z = tile / softcap
115	    AscendC::Muls(tile, tile, 1.0f / softcapVal, count);
116	    // e_pos = exp(2 * z)
117	    AscendC::Muls(tile, tile, 2.0f, count);
118	    AscendC::Exp(tile, tile, count);
119	    // tanh = (e_pos - 1) / (e_pos + 1)
120	    // tmp = e_pos + 1  (save in tmpBuf)
121	    AscendC::Adds(tmpBuf, tile, 1.0f, count);
122	    // tile = e_pos - 1
123	    AscendC::Adds(tile, tile, -1.0f, count);
124	    // tile = (e_pos - 1) / (e_pos + 1) = tanh
125	    AscendC::Div(tile, tile, tmpBuf, count);
126	    // softcapped = tanh * softcap
127	    AscendC::Muls(tile, tile, softcapVal, count);
128	}
129	
130	// =========================================================================
131	// Strategy 1: merge_n — preferred when N <= 1024
132	// Processes rowFactor rows at a time. Full row softcapping + softmax in UB.
133	// =========================================================================
134	
135	template <typename dataType>
136	class SoftmaxSoftcapMergeNKernel {
137	public:
138	    __aicore__ inline void Init(
139	        GM_ADDR x, GM_ADDR y,
140	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
141	        int32_t tasksPerCore, int32_t rowFactor, float softcapVal)
142	    {
143	        this->M = M;
144	        this->N = N;
145	        this->blockM = blockM;
146	        this->usedCoreNum = usedCoreNum;
147	        this->tasksPerCore = tasksPerCore;
148	        this->rowFactor = rowFactor;
149	        this->softcapVal = softcapVal;
150	
151	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), static_cast<uint64_t>(M) * N);
152	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(M) * N);
153	
154	        if ASCEND_IS_AIV { InitAivBuffers(); }
155	    }
156	
157	    __aicore__ inline void InitAivBuffers()
158	    {
159	        subBlockRows_ = blockM / AscendC::GetSubBlockNum();
160	        rowLoops_ = subBlockRows_ / rowFactor;
161	
162	        pipe.InitBuffer(xInQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
163	        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
164	        pipe.InitBuffer(tmpBuf_, kMergeRowFactor * N * sizeof(float));
165	        pipe.InitBuffer(reduceBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
166	        pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
167	        pipe.InitBuffer(bcastMaxTmpBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
168	        pipe.InitBuffer(bcastSumTmpBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
169	        if constexpr (!std::is_same_v<dataType, float>) {
170	            pipe.InitBuffer(xCastBuf_, kMergeRowFactor * N * sizeof(float));
171	            pipe.InitBuffer(yCastBuf_, kMergeRowFactor * N * sizeof(float));
172	        }
173	    }
174	
175	    __aicore__ inline void Process()
176	    {
177	        if ASCEND_IS_AIV {
178	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
179	            const int subBlockIdx = AscendC::GetSubBlockIdx();
180	
181	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
182	                const int bx = coreIdx * tasksPerCore + localIdx;
183	                if (bx >= (M + blockM - 1) / blockM) {
184	                    continue;
185	                }
186	
187	                for (int r = 0; r < rowLoops_; ++r) {
188	                    const int rowBase = bx * blockM + subBlockIdx * subBlockRows_ + r * rowFactor;
189	                    const int validRows = M - rowBase;
190	                    if (validRows > 0) {
191	                        const int actualRows = (validRows >= kMergeRowFactor) ? kMergeRowFactor : validRows;
192	                        ProcessRows(rowBase, actualRows);
193	                    }
194	                }
195	            }
196	        }
197	    }
198	
199	private:
200	    __aicore__ inline void ProcessSingleRow(int rowIdx)
201	    {
202	        // CopyIn one row
203	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
204	        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
205	        xInQueue_.EnQue(xInLocal_);
206	
207	        // Compute
208	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
209	        xInLocal_ = xInQueue_.DeQue<dataType>();
210	        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, N);
211	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
212	
213	        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
214	        sumLocal_ = sumBuf_.Get<float>();
215	        tmpLocal_ = tmpBuf_.Get<float>();
216	
217	        // Softcapping in-place
218	        SoftcapTile(xLocal_, tmpLocal_, static_cast<uint32_t>(N), softcapVal);
219	
220	        // Softmax on one row using ReduceSum (R-block scalar fallback)
221	        AscendC::ReduceMax<float>(sumLocal_, xLocal_, reduceTmpLocal_, N);
222	        float rowMax = sumLocal_.GetValue(0);
223	        AscendC::PipeBarrier<PIPE_ALL>();
224	
225	        AscendC::Adds(xLocal_, xLocal_, -rowMax, N);
226	        AscendC::Exp(xLocal_, xLocal_, N);
227	        AscendC::ReduceSum<float>(sumLocal_, xLocal_, reduceTmpLocal_, N);
228	        float rowSum = sumLocal_.GetValue(0);
229	        AscendC::PipeBarrier<PIPE_ALL>();
230	
231	        float invSum = (rowSum > 0.0f) ? (1.0f / rowSum) : 1.0f;
232	        AscendC::Muls(yLocal_, xLocal_, invSum, N);
233	
234	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, N);
235	
236	        xInQueue_.FreeTensor(xInLocal_);
237	        yOutQueue_.EnQue(yOutLocal_);
238	
239	        // CopyOut
240	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
241	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N], yOutLocal_, static_cast<uint32_t>(N));
242	        yOutQueue_.FreeTensor(yOutLocal_);
243	    }
244	
245	    __aicore__ inline void ProcessRows(int rowBase, int actualRows)
246	    {
247	        if (actualRows < kMergeRowFactor) {
248	            for (int r = 0; r < actualRows; ++r) {
249	                ProcessSingleRow(rowBase + r);
250	            }
251	            return;
252	        }
253	
254	        const int tileSize = kMergeRowFactor * N;
255	
256	        // CopyIn
257	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
258	        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowBase) * N], static_cast<uint32_t>(tileSize));
259	        xInQueue_.EnQue(xInLocal_);
260	
261	        // Compute
262	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
263	        xInLocal_ = xInQueue_.DeQue<dataType>();
264	        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, tileSize);
265	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
266	
267	        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
268	        sumLocal_ = sumBuf_.Get<float>();
269	        tmpLocal_ = tmpBuf_.Get<float>();
270	
271	        // Softcapping
272	        SoftcapTile(xLocal_, tmpLocal_, static_cast<uint32_t>(tileSize), softcapVal);
273	
274	        // Softmax: reduce_max over dim=-1 (AR pattern)
275	        const uint32_t reduceShape[2] = {
276	            static_cast<uint32_t>(kMergeRowFactor),
277	            static_cast<uint32_t>(N),
278	        };
279	        AscendC::ReduceMax<float, AscendC::Pattern::Reduce::AR, false>(
280	            sumLocal_, xLocal_, reduceTmpLocal_, reduceShape, true);
281	
282	        // Broadcast max
283	        const uint32_t maxSrcShape[2] = {static_cast<uint32_t>(kMergeRowFactor), 1U};
284	        const uint32_t maxDstShape[2] = {static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};
285	        AscendC::Duplicate(tmpLocal_, AscendC::LocalTensor<float>(tmpLocal_.Get()), tileSize);
286	        bcastMaxTmpLocal_ = bcastMaxTmpBuf_.Get<uint8_t>();
287	        AscendC::Broadcast<float, 2, 1>(
288	            tmpLocal_, sumLocal_, maxDstShape, maxSrcShape, bcastMaxTmpLocal_);
289	
290	        // sub max, exp, reduce_sum
291	        AscendC::Sub(xLocal_, xLocal_, tmpLocal_, tileSize);
292	        AscendC::Exp(xLocal_, xLocal_, tileSize);
293	
294	        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
295	            sumLocal_, xLocal_, reduceTmpLocal_, reduceShape, true);
296	
297	        // Broadcast sum
298	        AscendC::Duplicate(tmpLocal_, AscendC::LocalTensor<float>(tmpLocal_.Get()), tileSize);
299	        bcastSumTmpLocal_ = bcastSumTmpBuf_.Get<uint8_t>();
300	        AscendC::Broadcast<float, 2, 1>(
301	            tmpLocal_, sumLocal_, maxDstShape, maxSrcShape, bcastSumTmpLocal_);
302	
303	        // div by sum
304	        AscendC::Div(yLocal_, xLocal_, tmpLocal_, tileSize);
305	
306	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, tileSize);
307	
308	        xInQueue_.FreeTensor(xInLocal_);
309	        yOutQueue_.EnQue(yOutLocal_);
310	
311	        // CopyOut
312	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
313	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowBase) * N], yOutLocal_, static_cast<uint32_t>(tileSize));
314	        yOutQueue_.FreeTensor(yOutLocal_);
315	    }
316	
317	    int32_t M = 0;
318	    int32_t N = 0;
319	    int32_t blockM = 0;
320	    int32_t usedCoreNum = 0;
321	    int32_t tasksPerCore = 0;
322	    int32_t rowFactor = 0;
323	    float softcapVal = 30.0f;
324	    int subBlockRows_ = 0;
325	    int rowLoops_ = 0;
326	
327	    AscendC::TPipe pipe;
328	    AscendC::GlobalTensor<dataType> xGM_;
329	    AscendC::GlobalTensor<dataType> yGM_;
330	
331	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
332	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
333	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;
334	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
335	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
336	    AscendC::TBuf<AscendC::TPosition::VECCALC> bcastMaxTmpBuf_;
337	    AscendC::TBuf<AscendC::TPosition::VECCALC> bcastSumTmpBuf_;
338	    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
339	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
340	
341	    AscendC::LocalTensor<dataType> xInLocal_;
342	    AscendC::LocalTensor<dataType> yOutLocal_;
343	    AscendC::LocalTensor<float> xLocal_;
344	    AscendC::LocalTensor<float> yLocal_;
345	    AscendC::LocalTensor<float> tmpLocal_;
346	    AscendC::LocalTensor<uint8_t> reduceTmpLocal_;
347	    AscendC::LocalTensor<float> sumLocal_;
348	    AscendC::LocalTensor<uint8_t> bcastMaxTmpLocal_;
349	    AscendC::LocalTensor<uint8_t> bcastSumTmpLocal_;
350	};
351	
352	// =========================================================================
353	// Strategy 2: splitd — preferred when N > 1024
354	// 3-pass online softmax with re-softcapping per pass, tiling along N.
355	// =========================================================================
356	
357	template <typename dataType>
358	class SoftmaxSoftcapSplitDKernel {
359	public:
360	    __aicore__ inline void Init(
361	        GM_ADDR x, GM_ADDR y,
362	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
363	        int32_t tasksPerCore, float softcapVal)
364	    {
365	        this->M = M;
366	        this->N = N;
367	        this->blockM = blockM;
368	        this->usedCoreNum = usedCoreNum;
369	        this->tasksPerCore = tasksPerCore;
370	        this->softcapVal = softcapVal;
371	
372	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), static_cast<uint64_t>(M) * N);
373	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(M) * N);
374	
375	        if ASCEND_IS_AIV { InitAivBuffers(); }
376	    }
377	
378	    __aicore__ inline void InitAivBuffers()
379	    {
380	        subBlockRows_ = blockM / AscendC::GetSubBlockNum();
381	
382	        pipe.InitBuffer(xInQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
383	        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
384	        pipe.InitBuffer(tmpBuf_, kBlockN * sizeof(float));
385	        pipe.InitBuffer(reduceBuf_, 2 * kBlockN * sizeof(uint8_t));
386	        pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
387	        if constexpr (!std::is_same_v<dataType, float>) {
388	            pipe.InitBuffer(xCastBuf_, kBlockN * sizeof(float));
389	            pipe.InitBuffer(yCastBuf_, kBlockN * sizeof(float));
390	        }
391	    }
392	
393	    __aicore__ inline void Process()
394	    {
395	        if ASCEND_IS_AIV {
396	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
397	            const int subBlockIdx = AscendC::GetSubBlockIdx();
398	
399	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
400	                const int bx = coreIdx * tasksPerCore + localIdx;
401	                if (bx >= (M + blockM - 1) / blockM) {
402	                    continue;
403	                }
404	
405	                for (int row = 0; row < subBlockRows_; ++row) {
406	                    const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
407	                    if (rowIdx < M) {
408	                        ProcessRow(rowIdx);
409	                    }
410	                }
411	            }
412	        }
413	    }
414	
415	private:
416	    __aicore__ inline int32_t NumTiles() const
417	    {
418	        return (N + kBlockN - 1) / kBlockN;
419	    }
420	
421	    __aicore__ inline int32_t GetValidN(int32_t colBase) const
422	    {
423	        return (colBase + kBlockN <= N) ? kBlockN : (N - colBase);
424	    }
425	
426	    __aicore__ inline void ProcessRow(int32_t rowIdx)
427	    {
428	        // ---- Pass 1: find global max ----
429	        float globalMax = -3.402823466e+38f;
430	        for (int by = 0; by < NumTiles(); ++by) {
431	            const int colBase = by * kBlockN;
432	            const int validN = GetValidN(colBase);
433	
434	            // CopyIn
435	            xInLocal_ = xInQueue_.AllocTensor<dataType>();
436	            LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N + colBase],
437	                       static_cast<uint32_t>(validN));
438	            xInQueue_.EnQue(xInLocal_);
439	
440	            // Compute tile max after softcap
441	            xInLocal_ = xInQueue_.DeQue<dataType>();
442	            PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);
443	            tmpLocal_ = tmpBuf_.Get<float>();
444	            SoftcapTile(xLocal_, tmpLocal_, static_cast<uint32_t>(validN), softcapVal);
445	
446	            reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
447	            sumLocal_ = sumBuf_.Get<float>();
448	            AscendC::ReduceMax<float>(sumLocal_, xLocal_, reduceTmpLocal_, validN);
449	            float tileMax = sumLocal_.GetValue(0);
450	            AscendC::PipeBarrier<PIPE_ALL>();
451	            if (tileMax > globalMax) {
452	                globalMax = tileMax;
453	            }
454	
455	            xInQueue_.FreeTensor(xInLocal_);
456	        }
457	
458	        // ---- Pass 2: compute exp sum ----
459	        float globalSum = 0.0f;
460	        for (int by = 0; by < NumTiles(); ++by) {
461	            const int colBase = by * kBlockN;
462	            const int validN = GetValidN(colBase);
463	
464	            // CopyIn
465	            xInLocal_ = xInQueue_.AllocTensor<dataType>();
466	            LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N + colBase],
467	                       static_cast<uint32_t>(validN));
468	            xInQueue_.EnQue(xInLocal_);
469	
470	            // Compute exp(x - globalMax)
471	            xInLocal_ = xInQueue_.DeQue<dataType>();
472	            PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);
473	            tmpLocal_ = tmpBuf_.Get<float>();
474	            SoftcapTile(xLocal_, tmpLocal_, static_cast<uint32_t>(validN), softcapVal);
475	
476	            AscendC::Adds(xLocal_, xLocal_, -globalMax, validN);
477	            AscendC::Exp(xLocal_, xLocal_, validN);
478	
479	            reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
480	            sumLocal_ = sumBuf_.Get<float>();
481	            AscendC::ReduceSum<float>(sumLocal_, xLocal_, reduceTmpLocal_, validN);
482	            float tileSum = sumLocal_.GetValue(0);
483	            AscendC::PipeBarrier<PIPE_ALL>();
484	            globalSum += tileSum;
485	
486	            xInQueue_.FreeTensor(xInLocal_);
487	        }
488	
489	        // ---- Pass 3: normalize and write out ----
490	        float invSum = (globalSum > 0.0f) ? (1.0f / globalSum) : 1.0f;
491	        for (int by = 0; by < NumTiles(); ++by) {
492	            const int colBase = by * kBlockN;
493	            const int validN = GetValidN(colBase);
494	
495	            // CopyIn
496	            xInLocal_ = xInQueue_.AllocTensor<dataType>();
497	            LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N + colBase],
498	                       static_cast<uint32_t>(validN));
499	            xInQueue_.EnQue(xInLocal_);
500	
501	            // Compute
502	            yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
503	            xInLocal_ = xInQueue_.DeQue<dataType>();
504	            PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);
505	            PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
506	
507	            tmpLocal_ = tmpBuf_.Get<float>();
508	            SoftcapTile(xLocal_, tmpLocal_, static_cast<uint32_t>(validN), softcapVal);
509	
510	            AscendC::Adds(xLocal_, xLocal_, -globalMax, validN);
511	            AscendC::Exp(xLocal_, xLocal_, validN);
512	            AscendC::Muls(yLocal_, xLocal_, invSum, validN);
513	
514	            FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, validN);
515	
516	            xInQueue_.FreeTensor(xInLocal_);
517	            yOutQueue_.EnQue(yOutLocal_);
518	
519	            // CopyOut
520	            yOutLocal_ = yOutQueue_.DeQue<dataType>();
521	            StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N + colBase],
522	                        yOutLocal_, static_cast<uint32_t>(validN));
523	            yOutQueue_.FreeTensor(yOutLocal_);
524	        }
525	    }
526	
527	    int32_t M = 0;
528	    int32_t N = 0;
529	    int32_t blockM = 0;
530	    int32_t usedCoreNum = 0;
531	    int32_t tasksPerCore = 0;
532	    float softcapVal = 30.0f;
533	    int subBlockRows_ = 0;
534	
535	    AscendC::TPipe pipe;
536	    AscendC::GlobalTensor<dataType> xGM_;
537	    AscendC::GlobalTensor<dataType> yGM_;
538	
539	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
540	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
541	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;
542	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
543	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
544	    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
545	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
546	
547	    AscendC::LocalTensor<dataType> xInLocal_;
548	    AscendC::LocalTensor<dataType> yOutLocal_;
549	    AscendC::LocalTensor<float> xLocal_;
550	    AscendC::LocalTensor<float> yLocal_;
551	    AscendC::LocalTensor<float> tmpLocal_;
552	    AscendC::LocalTensor<uint8_t> reduceTmpLocal_;
553	    AscendC::LocalTensor<float> sumLocal_;
554	};
555	
556	// =========================================================================
557	// Dispatch helper
558	// =========================================================================
559	
560	template <template <typename> class Kernel, typename... ExtraArgs>
561	__aicore__ inline void DispatchSoftmaxSoftcap(
562	    GM_ADDR x, GM_ADDR y,
563	    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
564	    int32_t tasksPerCore, float softcapVal,
565	    int64_t dtypeFlag, ExtraArgs... extraArgs)
566	{
567	    if (dtypeFlag == 0) {
568	        Kernel<float> kernel;
569	        kernel.Init(x, y, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., softcapVal);
570	        kernel.Process();
571	    } else if (dtypeFlag == 1) {
572	        Kernel<half> kernel;
573	        kernel.Init(x, y, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., softcapVal);
574	        kernel.Process();
575	    } else {
576	        Kernel<bfloat16_t> kernel;
577	        kernel.Init(x, y, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., softcapVal);
578	        kernel.Process();
579	    }
580	}
581	
582	// =========================================================================
583	// Kernel entry points
584	// dtypeFlag: 0=fp32, 1=fp16, 2=bf16
585	// =========================================================================
586	
587	extern "C" __global__ __aicore__ void attention_softmax_softcap_dropout_merge_n(
588	    GM_ADDR x, GM_ADDR y,
589	    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
590	    int32_t tasksPerCore, int32_t rowFactor, float softcapVal,
591	    int64_t dtypeFlag)
592	{
593	    DispatchSoftmaxSoftcap<SoftmaxSoftcapMergeNKernel>(
594	        x, y, M, N, blockM, usedCoreNum, tasksPerCore,
595	        softcapVal, dtypeFlag, rowFactor);
596	}
597	
598	extern "C" __global__ __aicore__ void attention_softmax_softcap_dropout_splitd(
599	    GM_ADDR x, GM_ADDR y,
600	    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
601	    int32_t tasksPerCore, float softcapVal,
602	    int64_t dtypeFlag)
603	{
604	    DispatchSoftmaxSoftcap<SoftmaxSoftcapSplitDKernel>(
605	        x, y, M, N, blockM, usedCoreNum, tasksPerCore,
606	        softcapVal, dtypeFlag);
607	}
