// AscendC AttentionSoftmaxWithSoftcappingAndDropout kernel
// Two strategies: merge_n (N <= 1024), splitd (N > 1024)
// Softcapping: tanh(x / SOFTCAP) * SOFTCAP
// tanh(z) = (exp(2*z) - 1) / (exp(2*z) + 1)
// Supports float32, float16, bfloat16

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t kMergeRowFactor = 8;
constexpr int32_t kBlockN = 1024;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

template <typename T>
__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) {
        return AscendC::RoundMode::CAST_ROUND;
    }
    return AscendC::RoundMode::CAST_NONE;
}

// Prepare input: cast to float32 if needed
template <typename T>
__aicore__ inline void PrepareInputTensorHelper(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

// Prepare output: get output buffer for float32, optionally from cast buffer
template <typename T>
__aicore__ inline void PrepareOutputTensorHelper(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &out,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = out.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
    }
}

// Finalize output: cast back from float32 to T if needed
template <typename T>
__aicore__ inline void FinalizeOutputTensorHelper(
    AscendC::LocalTensor<T> &out,
    AscendC::LocalTensor<float> &src,
    int32_t count)
{
    if constexpr (!std::is_same_v<T, float>) {
        AscendC::Cast(out, src, OutputRoundModeHelper<T>(), count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

// ---------------------------------------------------------------------------
// Softcapping + Softmax compute (operates on float32 tiles)
// ---------------------------------------------------------------------------

// Apply softcapping in-place on a float32 tile of given count
// tanh decomposition: tanh(z) = (exp(2*z) - 1) / (exp(2*z) + 1)
__aicore__ inline void SoftcapTile(
    AscendC::LocalTensor<float> &tile,
    AscendC::LocalTensor<float> &tmpBuf,
    uint32_t count,
    float softcapVal)
{
    // z = tile / softcap
    AscendC::Muls(tile, tile, 1.0f / softcapVal, count);
    // e_pos = exp(2 * z)
    AscendC::Muls(tile, tile, 2.0f, count);
    AscendC::Exp(tile, tile, count);
    // tanh = (e_pos - 1) / (e_pos + 1)
    // tmp = e_pos + 1  (save in tmpBuf)
    AscendC::Adds(tmpBuf, tile, 1.0f, count);
    // tile = e_pos - 1
    AscendC::Adds(tile, tile, -1.0f, count);
    // tile = (e_pos - 1) / (e_pos + 1) = tanh
    AscendC::Div(tile, tile, tmpBuf, count);
    // softcapped = tanh * softcap
    AscendC::Muls(tile, tile, softcapVal, count);
}

// =========================================================================
// Strategy 1: merge_n — preferred when N <= 1024
// Processes rowFactor rows at a time. Full row softcapping + softmax in UB.
// =========================================================================

template <typename dataType>
class SoftmaxSoftcapMergeNKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y,
        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
        int32_t tasksPerCore, int32_t rowFactor, float softcapVal)
    {
        this->M = M;
        this->N = N;
        this->blockM = blockM;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;
        this->rowFactor = rowFactor;
        this->softcapVal = softcapVal;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), static_cast<uint64_t>(M) * N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(M) * N);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        subBlockRows_ = blockM / AscendC::GetSubBlockNum();
        rowLoops_ = subBlockRows_ / rowFactor;

        pipe.InitBuffer(xInQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
        pipe.InitBuffer(tmpBuf_, kMergeRowFactor * N * sizeof(float));
        pipe.InitBuffer(reduceFloatBuf_, kMergeRowFactor * N * sizeof(float));
        pipe.InitBuffer(reduceU8Buf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
        pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
        pipe.InitBuffer(bcastMaxTmpBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
        pipe.InitBuffer(bcastSumTmpBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(xCastBuf_, kMergeRowFactor * N * sizeof(float));
            pipe.InitBuffer(yCastBuf_, kMergeRowFactor * N * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= (M + blockM - 1) / blockM) {
                    continue;
                }

                for (int r = 0; r < rowLoops_; ++r) {
                    const int rowBase = bx * blockM + subBlockIdx * subBlockRows_ + r * rowFactor;
                    const int validRows = M - rowBase;
                    if (validRows > 0) {
                        const int actualRows = (validRows >= kMergeRowFactor) ? kMergeRowFactor : validRows;
                        ProcessRows(rowBase, actualRows);
                    }
                }
            }
        }
    }

private:
    __aicore__ inline void ProcessSingleRow(int rowIdx)
    {
        // CopyIn one row
        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
        xInQueue_.EnQue(xInLocal_);

        // Compute
        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
        xInLocal_ = xInQueue_.DeQue<dataType>();
        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, N);
        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);

        reduceFloatLocal_ = reduceFloatBuf_.Get<float>();
        sumLocal_ = sumBuf_.Get<float>();
        tmpLocal_ = tmpBuf_.Get<float>();

        // Softcapping in-place
        SoftcapTile(xLocal_, tmpLocal_, static_cast<uint32_t>(N), softcapVal);

        // Softmax on one row: reduce_max → sub → exp → reduce_sum → div
        AscendC::ReduceMax(sumLocal_, xLocal_, reduceFloatLocal_, N);
        float rowMax = sumLocal_.GetValue(0);
        AscendC::PipeBarrier<PIPE_ALL>();

        AscendC::Adds(xLocal_, xLocal_, -rowMax, N);
        AscendC::Exp(xLocal_, xLocal_, N);
        AscendC::ReduceSum(sumLocal_, xLocal_, reduceFloatLocal_, N);
        float rowSum = sumLocal_.GetValue(0);
        AscendC::PipeBarrier<PIPE_ALL>();

        float invSum = (rowSum > 0.0f) ? (1.0f / rowSum) : 1.0f;
        AscendC::Muls(yLocal_, xLocal_, invSum, N);

        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, N);

        xInQueue_.FreeTensor(xInLocal_);
        yOutQueue_.EnQue(yOutLocal_);

        // CopyOut
        yOutLocal_ = yOutQueue_.DeQue<dataType>();
        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N], yOutLocal_, static_cast<uint32_t>(N));
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    __aicore__ inline void ProcessRows(int rowBase, int actualRows)
    {
        if (actualRows < kMergeRowFactor) {
            for (int r = 0; r < actualRows; ++r) {
                ProcessSingleRow(rowBase + r);
            }
            return;
        }

        const int tileSize = kMergeRowFactor * N;

        // CopyIn
        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowBase) * N], static_cast<uint32_t>(tileSize));
        xInQueue_.EnQue(xInLocal_);

        // Compute
        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
        xInLocal_ = xInQueue_.DeQue<dataType>();
        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, tileSize);
        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);

        reduceU8Local_ = reduceU8Buf_.Get<uint8_t>();
        sumLocal_ = sumBuf_.Get<float>();
        tmpLocal_ = tmpBuf_.Get<float>();

        // Softcapping
        SoftcapTile(xLocal_, tmpLocal_, static_cast<uint32_t>(tileSize), softcapVal);

        // Softmax: reduce_max over dim=-1 (AR pattern)
        const uint32_t reduceShape[2] = {
            static_cast<uint32_t>(kMergeRowFactor),
            static_cast<uint32_t>(N),
        };
        AscendC::ReduceMax<float, AscendC::Pattern::Reduce::AR, false>(
            sumLocal_, xLocal_, reduceU8Local_, reduceShape, true);

        // Broadcast max
        const uint32_t maxSrcShape[2] = {static_cast<uint32_t>(kMergeRowFactor), 1U};
        const uint32_t maxDstShape[2] = {static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};
        AscendC::Duplicate(tmpLocal_, AscendC::LocalTensor<float>(tmpLocal_.Get()), tileSize);
        bcastMaxTmpLocal_ = bcastMaxTmpBuf_.Get<uint8_t>();
        AscendC::Broadcast<float, 2, 1>(
            tmpLocal_, sumLocal_, maxDstShape, maxSrcShape, bcastMaxTmpLocal_);

        // sub max, exp, reduce_sum
        AscendC::Sub(xLocal_, xLocal_, tmpLocal_, tileSize);
        AscendC::Exp(xLocal_, xLocal_, tileSize);

        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
            sumLocal_, xLocal_, reduceU8Local_, reduceShape, true);

        // Broadcast sum
        AscendC::Duplicate(tmpLocal_, AscendC::LocalTensor<float>(tmpLocal_.Get()), tileSize);
        bcastSumTmpLocal_ = bcastSumTmpBuf_.Get<uint8_t>();
        AscendC::Broadcast<float, 2, 1>(
            tmpLocal_, sumLocal_, maxDstShape, maxSrcShape, bcastSumTmpLocal_);

        // div by sum
        AscendC::Div(yLocal_, xLocal_, tmpLocal_, tileSize);

        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, tileSize);

        xInQueue_.FreeTensor(xInLocal_);
        yOutQueue_.EnQue(yOutLocal_);

        // CopyOut
        yOutLocal_ = yOutQueue_.DeQue<dataType>();
        StoreUbToGm(yGM_[static_cast<uint64_t>(rowBase) * N], yOutLocal_, static_cast<uint32_t>(tileSize));
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    int32_t M = 0;
    int32_t N = 0;
    int32_t blockM = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;
    int32_t rowFactor = 0;
    float softcapVal = 30.0f;
    int subBlockRows_ = 0;
    int rowLoops_ = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> xGM_;
    AscendC::GlobalTensor<dataType> yGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceFloatBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceU8Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bcastMaxTmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bcastSumTmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;

    AscendC::LocalTensor<dataType> xInLocal_;
    AscendC::LocalTensor<dataType> yOutLocal_;
    AscendC::LocalTensor<float> xLocal_;
    AscendC::LocalTensor<float> yLocal_;
    AscendC::LocalTensor<float> tmpLocal_;
    AscendC::LocalTensor<float> reduceFloatLocal_;
    AscendC::LocalTensor<uint8_t> reduceU8Local_;
    AscendC::LocalTensor<float> sumLocal_;
    AscendC::LocalTensor<uint8_t> bcastMaxTmpLocal_;
    AscendC::LocalTensor<uint8_t> bcastSumTmpLocal_;
};

// =========================================================================
// Strategy 2: splitd — preferred when N > 1024
// 3-pass online softmax with re-softcapping per pass, tiling along N.
// =========================================================================

template <typename dataType>
class SoftmaxSoftcapSplitDKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y,
        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
        int32_t tasksPerCore, float softcapVal)
    {
        this->M = M;
        this->N = N;
        this->blockM = blockM;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;
        this->softcapVal = softcapVal;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), static_cast<uint64_t>(M) * N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(M) * N);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        subBlockRows_ = blockM / AscendC::GetSubBlockNum();

        pipe.InitBuffer(xInQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
        pipe.InitBuffer(tmpBuf_, kBlockN * sizeof(float));
        pipe.InitBuffer(reduceFloatBuf_, kBlockN * sizeof(float));
        pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(xCastBuf_, kBlockN * sizeof(float));
            pipe.InitBuffer(yCastBuf_, kBlockN * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= (M + blockM - 1) / blockM) {
                    continue;
                }

                for (int row = 0; row < subBlockRows_; ++row) {
                    const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
                    if (rowIdx < M) {
                        ProcessRow(rowIdx);
                    }
                }
            }
        }
    }

private:
    __aicore__ inline int32_t NumTiles() const
    {
        return (N + kBlockN - 1) / kBlockN;
    }

    __aicore__ inline int32_t GetValidN(int32_t colBase) const
    {
        return (colBase + kBlockN <= N) ? kBlockN : (N - colBase);
    }

    __aicore__ inline void ProcessRow(int32_t rowIdx)
    {
        // ---- Pass 1: find global max ----
        float globalMax = -3.402823466e+38f;
        for (int by = 0; by < NumTiles(); ++by) {
            const int colBase = by * kBlockN;
            const int validN = GetValidN(colBase);

            // CopyIn
            xInLocal_ = xInQueue_.AllocTensor<dataType>();
            LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N + colBase],
                       static_cast<uint32_t>(validN));
            xInQueue_.EnQue(xInLocal_);

            // Compute tile max after softcap
            xInLocal_ = xInQueue_.DeQue<dataType>();
            PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);
            tmpLocal_ = tmpBuf_.Get<float>();
            SoftcapTile(xLocal_, tmpLocal_, static_cast<uint32_t>(validN), softcapVal);

            reduceFloatLocal_ = reduceFloatBuf_.Get<float>();
            sumLocal_ = sumBuf_.Get<float>();
            AscendC::ReduceMax(sumLocal_, xLocal_, reduceFloatLocal_, validN);
            float tileMax = sumLocal_.GetValue(0);
            AscendC::PipeBarrier<PIPE_ALL>();
            if (tileMax > globalMax) {
                globalMax = tileMax;
            }

            xInQueue_.FreeTensor(xInLocal_);
        }

        // ---- Pass 2: compute exp sum ----
        float globalSum = 0.0f;
        for (int by = 0; by < NumTiles(); ++by) {
            const int colBase = by * kBlockN;
            const int validN = GetValidN(colBase);

            // CopyIn
            xInLocal_ = xInQueue_.AllocTensor<dataType>();
            LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N + colBase],
                       static_cast<uint32_t>(validN));
            xInQueue_.EnQue(xInLocal_);

            // Compute exp(x - globalMax)
            xInLocal_ = xInQueue_.DeQue<dataType>();
            PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);
            tmpLocal_ = tmpBuf_.Get<float>();
            SoftcapTile(xLocal_, tmpLocal_, static_cast<uint32_t>(validN), softcapVal);

            AscendC::Adds(xLocal_, xLocal_, -globalMax, validN);
            AscendC::Exp(xLocal_, xLocal_, validN);

            reduceFloatLocal_ = reduceFloatBuf_.Get<float>();
            sumLocal_ = sumBuf_.Get<float>();
            AscendC::ReduceSum(sumLocal_, xLocal_, reduceFloatLocal_, validN);
            float tileSum = sumLocal_.GetValue(0);
            AscendC::PipeBarrier<PIPE_ALL>();
            globalSum += tileSum;

            xInQueue_.FreeTensor(xInLocal_);
        }

        // ---- Pass 3: normalize and write out ----
        float invSum = (globalSum > 0.0f) ? (1.0f / globalSum) : 1.0f;
        for (int by = 0; by < NumTiles(); ++by) {
            const int colBase = by * kBlockN;
            const int validN = GetValidN(colBase);

            // CopyIn
            xInLocal_ = xInQueue_.AllocTensor<dataType>();
            LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N + colBase],
                       static_cast<uint32_t>(validN));
            xInQueue_.EnQue(xInLocal_);

            // Compute
            yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
            xInLocal_ = xInQueue_.DeQue<dataType>();
            PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);
            PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);

            tmpLocal_ = tmpBuf_.Get<float>();
            SoftcapTile(xLocal_, tmpLocal_, static_cast<uint32_t>(validN), softcapVal);

            AscendC::Adds(xLocal_, xLocal_, -globalMax, validN);
            AscendC::Exp(xLocal_, xLocal_, validN);
            AscendC::Muls(yLocal_, xLocal_, invSum, validN);

            FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, validN);

            xInQueue_.FreeTensor(xInLocal_);
            yOutQueue_.EnQue(yOutLocal_);

            // CopyOut
            yOutLocal_ = yOutQueue_.DeQue<dataType>();
            StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N + colBase],
                        yOutLocal_, static_cast<uint32_t>(validN));
            yOutQueue_.FreeTensor(yOutLocal_);
        }
    }

    int32_t M = 0;
    int32_t N = 0;
    int32_t blockM = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;
    float softcapVal = 30.0f;
    int subBlockRows_ = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> xGM_;
    AscendC::GlobalTensor<dataType> yGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceFloatBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;

    AscendC::LocalTensor<dataType> xInLocal_;
    AscendC::LocalTensor<dataType> yOutLocal_;
    AscendC::LocalTensor<float> xLocal_;
    AscendC::LocalTensor<float> yLocal_;
    AscendC::LocalTensor<float> tmpLocal_;
    AscendC::LocalTensor<float> reduceFloatLocal_;
    AscendC::LocalTensor<float> sumLocal_;
};

// =========================================================================
// Dispatch helper
// =========================================================================

template <template <typename> class Kernel, typename... ExtraArgs>
__aicore__ inline void DispatchSoftmaxSoftcap(
    GM_ADDR x, GM_ADDR y,
    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
    int32_t tasksPerCore, float softcapVal,
    int64_t dtypeFlag, ExtraArgs... extraArgs)
{
    if (dtypeFlag == 0) {
        Kernel<float> kernel;
        kernel.Init(x, y, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., softcapVal);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        Kernel<half> kernel;
        kernel.Init(x, y, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., softcapVal);
        kernel.Process();
    } else {
        Kernel<bfloat16_t> kernel;
        kernel.Init(x, y, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., softcapVal);
        kernel.Process();
    }
}

// =========================================================================
// Kernel entry points
// dtypeFlag: 0=fp32, 1=fp16, 2=bf16
// =========================================================================

extern "C" __global__ __aicore__ void attention_softmax_softcap_dropout_merge_n(
    GM_ADDR x, GM_ADDR y,
    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
    int32_t tasksPerCore, int32_t rowFactor, float softcapVal,
    int64_t dtypeFlag)
{
    DispatchSoftmaxSoftcap<SoftmaxSoftcapMergeNKernel>(
        x, y, M, N, blockM, usedCoreNum, tasksPerCore,
        softcapVal, dtypeFlag, rowFactor);
}

extern "C" __global__ __aicore__ void attention_softmax_softcap_dropout_splitd(
    GM_ADDR x, GM_ADDR y,
    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
    int32_t tasksPerCore, float softcapVal,
    int64_t dtypeFlag)
{
    DispatchSoftmaxSoftcap<SoftmaxSoftcapSplitDKernel>(
        x, y, M, N, blockM, usedCoreNum, tasksPerCore,
        softcapVal, dtypeFlag);
}
