// AscendC AttentionSoftmaxWithSoftcappingAndDropout kernel
// Processes one row at a time with float32 intermediate precision.
// Softcapping: tanh(x / SOFTCAP) * SOFTCAP
// tanh(z) = (exp(2*z) - 1) / (exp(2*z) + 1)
// Supports float32, float16, bfloat16

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t kBlockN = 1024;
constexpr int32_t kBlockM = 64;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

template <typename T>
__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) {
        return AscendC::RoundMode::CAST_ROUND;
    }
    return AscendC::RoundMode::CAST_NONE;
}

// Prepare input: cast to float32 if needed
template <typename T>
__aicore__ inline void PrepareInput(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

template <typename T>
__aicore__ inline void PrepareOutput(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &out,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = out.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
    }
}

template <typename T>
__aicore__ inline void FinalizeOutput(
    AscendC::LocalTensor<T> &out,
    AscendC::LocalTensor<float> &src,
    int32_t count)
{
    if constexpr (!std::is_same_v<T, float>) {
        AscendC::Cast(out, src, OutputRoundModeHelper<T>(), count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

// ---------------------------------------------------------------------------
// tanh decomposition: tanh(z) = (exp(2*z) - 1) / (exp(2*z) + 1)
// Operates in-place on tile, clobbers tmp
// ---------------------------------------------------------------------------
__aicore__ inline void TanhTile(
    AscendC::LocalTensor<float> &tile,
    AscendC::LocalTensor<float> &tmp,
    uint32_t count)
{
    // exp(2*z)
    AscendC::Muls(tile, tile, 2.0f, count);
    AscendC::Exp(tile, tile, count);
    // tanh = (e_pos - 1) / (e_pos + 1)
    AscendC::Adds(tmp, tile, 1.0f, count);
    AscendC::Adds(tile, tile, -1.0f, count);
    AscendC::Div(tile, tile, tmp, count);
}

// =========================================================================
// Strategy 1: merge_n (N <= 1024) — single row at a time
// =========================================================================

template <typename dataType>
class SoftmaxSoftcapMergeNKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y,
        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
        int32_t tasksPerCore, float softcapVal)
    {
        this->M = M;
        this->N = N;
        this->blockM = blockM;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;
        this->softcapVal = softcapVal;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), static_cast<uint64_t>(M) * N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(M) * N);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        subBlockRows_ = blockM / AscendC::GetSubBlockNum();

        // One row of N elements for I/O, plus compute temp buffers
        pipe.InitBuffer(xInQueue_, BUFFER_NUM, N * sizeof(dataType));
        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, N * sizeof(dataType));
        pipe.InitBuffer(tmpBuf_, N * sizeof(float));
        pipe.InitBuffer(reduceWorkBuf_, N * sizeof(float));
        pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(xCastBuf_, N * sizeof(float));
            pipe.InitBuffer(yCastBuf_, N * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= (M + blockM - 1) / blockM) {
                    continue;
                }

                for (int row = 0; row < subBlockRows_; ++row) {
                    const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
                    if (rowIdx < M) {
                        ProcessSingleRow(rowIdx);
                    }
                }
            }
        }
    }

private:
    __aicore__ inline void ProcessSingleRow(int rowIdx)
    {
        // CopyIn
        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
        xInQueue_.EnQue(xInLocal_);

        // Allocate output
        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();

        // DeQue input
        xInLocal_ = xInQueue_.DeQue<dataType>();
        PrepareInput<dataType>(xLocal_, xInLocal_, xCastBuf_, N);
        PrepareOutput<dataType>(yLocal_, yOutLocal_, yCastBuf_);

        reduceWork_ = reduceWorkBuf_.Get<float>();
        sumLocal_ = sumBuf_.Get<float>();
        tmpLocal_ = tmpBuf_.Get<float>();

        // === Step 1: Softcapping ===
        // scaled = x / softcap
        AscendC::Muls(xLocal_, xLocal_, 1.0f / softcapVal, N);
        // tanh(scaled) in-place
        TanhTile(xLocal_, tmpLocal_, static_cast<uint32_t>(N));
        // softcapped = tanh * softcap
        AscendC::Muls(xLocal_, xLocal_, softcapVal, N);

        // === Step 2: Softmax ===
        // max = reduce_max
        AscendC::ReduceMax(sumLocal_, xLocal_, reduceWork_, N);
        float rowMax = sumLocal_.GetValue(0);
        AscendC::PipeBarrier<PIPE_ALL>();

        // x_shifted = x - max
        AscendC::Adds(xLocal_, xLocal_, -rowMax, N);
        // exp(x_shifted)
        AscendC::Exp(xLocal_, xLocal_, N);
        // sum = reduce_sum
        AscendC::ReduceSum(sumLocal_, xLocal_, reduceWork_, N);
        float rowSum = sumLocal_.GetValue(0);
        AscendC::PipeBarrier<PIPE_ALL>();

        float divScale = (rowSum > 0.0f) ? (1.0f / rowSum) : 1.0f;
        AscendC::Muls(yLocal_, xLocal_, divScale, N);

        // Cast and finalize output
        FinalizeOutput<dataType>(yOutLocal_, yLocal_, N);

        xInQueue_.FreeTensor(xInLocal_);
        yOutQueue_.EnQue(yOutLocal_);

        // CopyOut
        yOutLocal_ = yOutQueue_.DeQue<dataType>();
        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N], yOutLocal_, static_cast<uint32_t>(N));
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    int32_t M = 0;
    int32_t N = 0;
    int32_t blockM = kBlockM;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;
    float softcapVal = 30.0f;
    int subBlockRows_ = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> xGM_;
    AscendC::GlobalTensor<dataType> yGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceWorkBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;

    AscendC::LocalTensor<dataType> xInLocal_;
    AscendC::LocalTensor<dataType> yOutLocal_;
    AscendC::LocalTensor<float> xLocal_;
    AscendC::LocalTensor<float> yLocal_;
    AscendC::LocalTensor<float> tmpLocal_;
    AscendC::LocalTensor<float> reduceWork_;
    AscendC::LocalTensor<float> sumLocal_;
};

// =========================================================================
// Strategy 2: splitd (N > 1024) — 3-pass online softmax, tiling along N
// =========================================================================

template <typename dataType>
class SoftmaxSoftcapSplitDKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y,
        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
        int32_t tasksPerCore, float softcapVal)
    {
        this->M = M;
        this->N = N;
        this->blockM = blockM;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;
        this->softcapVal = softcapVal;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), static_cast<uint64_t>(M) * N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(M) * N);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        subBlockRows_ = blockM / AscendC::GetSubBlockNum();

        pipe.InitBuffer(xInQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
        pipe.InitBuffer(tmpBuf_, kBlockN * sizeof(float));
        pipe.InitBuffer(reduceWorkBuf_, kBlockN * sizeof(float));
        pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(xCastBuf_, kBlockN * sizeof(float));
            pipe.InitBuffer(yCastBuf_, kBlockN * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= (M + blockM - 1) / blockM) {
                    continue;
                }

                for (int row = 0; row < subBlockRows_; ++row) {
                    const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
                    if (rowIdx < M) {
                        ProcessRow(rowIdx);
                    }
                }
            }
        }
    }

private:
    __aicore__ inline int32_t NumTiles() const
    {
        return (N + kBlockN - 1) / kBlockN;
    }

    __aicore__ inline int32_t GetValidN(int32_t colBase) const
    {
        return (colBase + kBlockN <= N) ? kBlockN : (N - colBase);
    }

    __aicore__ inline void SoftcapAndCopy(
        AscendC::LocalTensor<float> &dst,
        AscendC::LocalTensor<dataType> &src,
        int32_t colBase, int32_t validN)
    {
        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx_) * N + colBase],
                   static_cast<uint32_t>(validN));
        xInQueue_.EnQue(xInLocal_);

        xInLocal_ = xInQueue_.DeQue<dataType>();
        PrepareInput<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);
        tmpLocal_ = tmpBuf_.Get<float>();

        // softcap = tanh(x / cap) * cap
        AscendC::Muls(xLocal_, xLocal_, 1.0f / softcapVal, validN);
        TanhTile(xLocal_, tmpLocal_, static_cast<uint32_t>(validN));
        AscendC::Muls(xLocal_, xLocal_, softcapVal, validN);

        xInQueue_.FreeTensor(xInLocal_);
    }

    __aicore__ inline void ProcessRow(int32_t rowIdx)
    {
        rowIdx_ = rowIdx;

        // ---- Pass 1: find global max ----
        float globalMax = -3.402823466e+38f;
        for (int by = 0; by < NumTiles(); ++by) {
            const int colBase = by * kBlockN;
            const int validN = GetValidN(colBase);

            xInLocal_ = xInQueue_.AllocTensor<dataType>();
            LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N + colBase],
                       static_cast<uint32_t>(validN));
            xInQueue_.EnQue(xInLocal_);

            xInLocal_ = xInQueue_.DeQue<dataType>();
            PrepareInput<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);
            tmpLocal_ = tmpBuf_.Get<float>();

            // Softcap + find max
            AscendC::Muls(xLocal_, xLocal_, 1.0f / softcapVal, validN);
            TanhTile(xLocal_, tmpLocal_, static_cast<uint32_t>(validN));
            AscendC::Muls(xLocal_, xLocal_, softcapVal, validN);

            reduceWork_ = reduceWorkBuf_.Get<float>();
            sumLocal_ = sumBuf_.Get<float>();
            AscendC::ReduceMax(sumLocal_, xLocal_, reduceWork_, validN);
            float tileMax = sumLocal_.GetValue(0);
            AscendC::PipeBarrier<PIPE_ALL>();
            if (tileMax > globalMax) {
                globalMax = tileMax;
            }

            xInQueue_.FreeTensor(xInLocal_);
        }

        // ---- Pass 2: compute exp sum ----
        float globalSum = 0.0f;
        for (int by = 0; by < NumTiles(); ++by) {
            const int colBase = by * kBlockN;
            const int validN = GetValidN(colBase);

            xInLocal_ = xInQueue_.AllocTensor<dataType>();
            LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N + colBase],
                       static_cast<uint32_t>(validN));
            xInQueue_.EnQue(xInLocal_);

            xInLocal_ = xInQueue_.DeQue<dataType>();
            PrepareInput<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);
            tmpLocal_ = tmpBuf_.Get<float>();

            // Softcap
            AscendC::Muls(xLocal_, xLocal_, 1.0f / softcapVal, validN);
            TanhTile(xLocal_, tmpLocal_, static_cast<uint32_t>(validN));
            AscendC::Muls(xLocal_, xLocal_, softcapVal, validN);

            // exp(x - globalMax)
            AscendC::Adds(xLocal_, xLocal_, -globalMax, validN);
            AscendC::Exp(xLocal_, xLocal_, validN);

            reduceWork_ = reduceWorkBuf_.Get<float>();
            sumLocal_ = sumBuf_.Get<float>();
            AscendC::ReduceSum(sumLocal_, xLocal_, reduceWork_, validN);
            float tileSum = sumLocal_.GetValue(0);
            AscendC::PipeBarrier<PIPE_ALL>();
            globalSum += tileSum;

            xInQueue_.FreeTensor(xInLocal_);
        }

        // ---- Pass 3: normalize and write out ----
        float invSum = (globalSum > 0.0f) ? (1.0f / globalSum) : 1.0f;
        for (int by = 0; by < NumTiles(); ++by) {
            const int colBase = by * kBlockN;
            const int validN = GetValidN(colBase);

            xInLocal_ = xInQueue_.AllocTensor<dataType>();
            LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N + colBase],
                       static_cast<uint32_t>(validN));
            xInQueue_.EnQue(xInLocal_);

            yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
            xInLocal_ = xInQueue_.DeQue<dataType>();
            PrepareInput<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);
            PrepareOutput<dataType>(yLocal_, yOutLocal_, yCastBuf_);

            tmpLocal_ = tmpBuf_.Get<float>();

            // Softcap
            AscendC::Muls(xLocal_, xLocal_, 1.0f / softcapVal, validN);
            TanhTile(xLocal_, tmpLocal_, static_cast<uint32_t>(validN));
            AscendC::Muls(xLocal_, xLocal_, softcapVal, validN);

            // Normalize
            AscendC::Adds(xLocal_, xLocal_, -globalMax, validN);
            AscendC::Exp(xLocal_, xLocal_, validN);
            AscendC::Muls(yLocal_, xLocal_, invSum, validN);

            FinalizeOutput<dataType>(yOutLocal_, yLocal_, validN);

            xInQueue_.FreeTensor(xInLocal_);
            yOutQueue_.EnQue(yOutLocal_);

            yOutLocal_ = yOutQueue_.DeQue<dataType>();
            StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N + colBase],
                        yOutLocal_, static_cast<uint32_t>(validN));
            yOutQueue_.FreeTensor(yOutLocal_);
        }
    }

    int32_t M = 0;
    int32_t N = 0;
    int32_t blockM = kBlockM;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;
    float softcapVal = 30.0f;
    int subBlockRows_ = 0;
    int32_t rowIdx_ = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> xGM_;
    AscendC::GlobalTensor<dataType> yGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceWorkBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;

    AscendC::LocalTensor<dataType> xInLocal_;
    AscendC::LocalTensor<dataType> yOutLocal_;
    AscendC::LocalTensor<float> xLocal_;
    AscendC::LocalTensor<float> yLocal_;
    AscendC::LocalTensor<float> tmpLocal_;
    AscendC::LocalTensor<float> reduceWork_;
    AscendC::LocalTensor<float> sumLocal_;
};

// =========================================================================
// Dispatch helper
// =========================================================================

template <template <typename> class Kernel>
__aicore__ inline void DispatchSoftmaxSoftcap(
    GM_ADDR x, GM_ADDR y,
    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
    int32_t tasksPerCore, float softcapVal, int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        Kernel<float> kernel;
        kernel.Init(x, y, M, N, blockM, usedCoreNum, tasksPerCore, softcapVal);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        Kernel<half> kernel;
        kernel.Init(x, y, M, N, blockM, usedCoreNum, tasksPerCore, softcapVal);
        kernel.Process();
    } else {
        Kernel<bfloat16_t> kernel;
        kernel.Init(x, y, M, N, blockM, usedCoreNum, tasksPerCore, softcapVal);
        kernel.Process();
    }
}

// =========================================================================
// Kernel entry points
// dtypeFlag: 0=fp32, 1=fp16, 2=bf16
// =========================================================================

extern "C" __global__ __aicore__ void attention_softmax_softcap_dropout_merge_n(
    GM_ADDR x, GM_ADDR y,
    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
    int32_t tasksPerCore, int32_t rowFactor, float softcapVal,
    int64_t dtypeFlag)
{
    (void)rowFactor;  // unused in single-row path
    DispatchSoftmaxSoftcap<SoftmaxSoftcapMergeNKernel>(
        x, y, M, N, blockM, usedCoreNum, tasksPerCore, softcapVal, dtypeFlag);
}

extern "C" __global__ __aicore__ void attention_softmax_softcap_dropout_splitd(
    GM_ADDR x, GM_ADDR y,
    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
    int32_t tasksPerCore, float softcapVal,
    int64_t dtypeFlag)
{
    DispatchSoftmaxSoftcap<SoftmaxSoftcapSplitDKernel>(
        x, y, M, N, blockM, usedCoreNum, tasksPerCore, softcapVal, dtypeFlag);
}
