            AscendC::Exp(xLocal_, xLocal_, validN);

            reduceWork_ = reduceWorkBuf_.Get<float>();
            sumLocal_ = sumBuf_.Get<float>();
            AscendC::ReduceSum(sumLocal_, xLocal_, reduceWork_, validN);
            float tileSum = sumLocal_.GetValue(0);
